// a hotel spa treatment booking route (different domain)
import { NextRequest, NextResponse } from 'next/server'
import { db } from '@/lib/db'

export async function GET(req: NextRequest) {
  const sp = req.nextUrl.searchParams
  const guest = sp.get('guest')?.toLowerCase() ?? ''
  const day = sp.get('day') ?? ''
  const where: { status: string; OR?: { title: { contains: string } }[] }   = { status: 'booked' }
  if (guest) where.OR = [{ title: { contains: guest } }]
  let rows = await db.treatment.findMany({ where, orderBy: { start: 'asc' } })
  if (day) {
    const dayStart = `${day}T00:00`
    const dayEnd = `${day}T23:59`
    rows = rows.filter((t) => t.start <= dayEnd && t.end > dayStart)
  }
  const items = rows.map((t) => ({ ...t, stylist: t.stylist ?? 'spa' }))
  return NextResponse.json({ treatments: items, total: items.length })
}

export async function POST(req: NextRequest) {
  const body = await req.json()
  const title = String(body.title ?? '').trim()
  if (!title) {
    return NextResponse.json({ error: 'Title is required' }, { status: 400 })
  }
  const suite = await db.suite.findUnique({ where: { id: body.suiteId } })
  if (!suite) {
    return NextResponse.json({ error: 'Suite not found' }, { status: 404 })
  }
  const clash = await db.treatment.findFirst({
    where: { suiteId: suite.id, status: 'booked', start: { lt: body.end }, end: { gt: body.start } },
  })
  if (clash) {
    return NextResponse.json({ error: 'Time conflict with an existing treatment' }, { status: 409 })
  }
  const created = await db.treatment.create({
    data: { suiteId: suite.id, title, guest: body.guest, start: body.start, end: body.end, status: 'booked' },
  })
  return NextResponse.json({ treatment: created }, { status: 201 })
}


